import styled from "styled-components";
import { categoriesState, selectedCategoryState } from "../atoms/todoAtom";
import { useRecoilState } from "recoil";

const Tabs = styled.div`
	/* display: grid; */
	/* grid-template-columns: repeat(4, 1fr); */
	display: flex;
	flex-wrap: wrap;
	margin:12px 0px;
	gap: 8px;
	/* border-bottom: 1px solid ${props => props.theme.bgColors.dimmed}; */
	/* border-bottom: 1px solid ${props => props.theme.bgColors.reversed}; */
`;

const Tab = styled.button<{isActive: boolean}>`
	display: inline-flex;
	width: auto;
	white-space: nowrap;
	text-align: center;
	font-size: 14px;
	font-weight: 400;
	padding: 6px 20px;
	border-radius: 12px; 
	background-color: ${(props) => props.theme.bgColors.dimmed};
	color: ${(props) => 
		props.isActive ? props.theme.brandColors.primary : props.theme.textColors.normal
	};
`;

function CategoryTabBar() {
	const [categories, setCategories] = useRecoilState(categoriesState);
	const [selectedCategory, setSelectedCategory] = useRecoilState(selectedCategoryState);
	const selectCategory = (cur: string) => {
		setSelectedCategory((prev) => prev === cur ? null : cur)
	};
	const addNewCategory = () => {
		console.log("add new category")
		const newCategoryName = prompt("카테고리 이름을 입려해주세요.") ?? "";
		if (validateCategory(newCategoryName)) {
			setCategories((prev) => [...prev, newCategoryName])
		}
	};

	const validateCategory = (newCategory: string | null) => {
		if (!newCategory) return false;

		const trimmed = newCategory.trim();
		if (trimmed.length < 1 || trimmed.length > 10) return false;

  	return !(categories.some( (c) => c === trimmed ));
	}

	return (
		<Tabs>
			{categories.map((category) => (
				<Tab 
					isActive={selectedCategory === category} 
					onClick={ () => selectCategory(category) }
				>
					{category}
				</Tab>	
			))}
			<Tab isActive={false} onClick={addNewCategory}>
				+
			</Tab>
		</Tabs>
	);
}

export default CategoryTabBar;
